1	import { describe, expect, it } from "vitest";
2	import type { CardRepository } from "../../ports/CardRepository";
3	import { consonants } from "../../script/data/symbols";
4	import { ScriptPropertyCard } from "../../script/entities/ScriptPropertyCard";
5	import type { CardPool } from "../../shared/CardPool";
6	import type { PropertyType } from "../../shared/types";
7	import { SrsSchedule } from "../../srs/value-objects/SrsSchedule";
8	import { VocabCard } from "../../vocabulary/entities/VocabCard";
9	import type { VocabEntry } from "../../vocabulary/types";
10	import type {
11		GameCardPool,
12		GameItemContent,
13		GameItemSource,
14		RandomSource,
15	} from "../types";
16	import { GameItemSelectionService } from "./GameItemSelectionService";
17	import { SymbolGameItemSource } from "./SymbolGameItemSource";
18	import { WordGameItemSource } from "./WordGameItemSource";
19	
20	function symbolContent(character: string, audioUrl?: string): GameItemContent {
21		return {
22			kind: "symbol",
23			symbolCharacter: character,
24			promptText: character,
25			correctAnswer: `name of ${character}`,
26			audioUrl,
27		};
28	}
29	
30	function wordContent(thaiWord: string, audioUrl?: string): GameItemContent {
31		return {
32			kind: "word",
33			thaiWord,
34			englishMeaning: `meaning of ${thaiWord}`,
35			audioUrl,
36		};
37	}
38	
39	function sourceOf(
40		pool: GameCardPool,
41		content: readonly GameItemContent[],
42	): GameItemSource {
43		return { pool, eligibleContent: () => [...content] };
44	}
45	
46	function vocabEntry(thai: string, audioUrl?: string): VocabEntry {
47		return {
48			thai,
49			romanization: thai,
50			word_class: "noun",
51			english: `meaning of ${thai}`,
52			rank: null,
53			frequency: 0,
54			mnemonic: null,
55			characters: [...thai],
56			syllables: [],
57			toneRules: [],
58			thai_audio_file: audioUrl ?? null,
59			english_audio_file: null,
60			image_file: null,
61			samples: [],
62			source: "test",
63		};
64	}
65	
66	function vocabCard(
67		id: string,
68		promptWord: string,
69		property: string,
70	): VocabCard {
71		return new VocabCard(
72			id,
73			"question",
74			"answer",
75			["answer"],
76			SrsSchedule.initial(),
77			promptWord,
78			property,
79		);
80	}
81	
82	function repositoryOf(
83		scriptCards: readonly ScriptPropertyCard[],
84		vocabCards: readonly VocabCard[],
85	): CardRepository {
86		return {
87			findById: () => null,
88			findDue: () => [],
89			findAll: (pool: CardPool) => {
90				if (pool === "script") return [...scriptCards];
91				if (pool === "vocab") return [...vocabCards];
92				return [];
93			},
94			save: () => {},
95			saveAll: () => {},
96			remove: () => {},
97		};
98	}
99	
100	function scripted(values: readonly number[]): RandomSource {
101		let index = 0;
102		return () => values[index++ % values.length] as number;
103	}
104	
105	const FIVE = ["1", "2", "3", "4", "5"].map((character) =>
106		symbolContent(character, `/audio/${character}.mp3`),
107	);
108	
109	const SCRIPT_ONLY = { pools: ["script"] as const };
110	
111	describe("GameItemSelectionService", () => {
112		it("returns exactly the requested count, one per distinct symbol", () => {
113			const service = new GameItemSelectionService([sourceOf("script", FIVE)]);
114	
115			const round = service.selectRound(
116				{ ...SCRIPT_ONLY, itemCount: 3 },
117				// A source that always names the first of what remains: only
118				// removing each drawn item keeps the three distinct.
119				scripted([0.0]),
120			);
121	
122			expect(round).toHaveLength(3);
123			expect(new Set(round.map((item) => item.symbolCharacter)).size).toBe(3);
124		});
125	
126		it("returns every eligible item when more are requested than exist", () => {
127			const service = new GameItemSelectionService([sourceOf("script", FIVE)]);
128	
129			const round = service.selectRound(
130				{ ...SCRIPT_ONLY, itemCount: 50 },
131				scripted([0.3, 0.8, 0.1]),
132			);
133	
134			expect(round).toHaveLength(5);
135			expect(new Set(round.map((item) => item.symbolCharacter)).size).toBe(5);
136		});
137	
138		it("returns an empty round when nothing is eligible", () => {
139			const service = new GameItemSelectionService([sourceOf("script", [])]);
140	
141			expect(
142				service.selectRound({ ...SCRIPT_ONLY, itemCount: 5 }, scripted([0.5])),
143			).toEqual([]);
144		});
145	
146		it("assigns the exact direction sequence a seeded source dictates", () => {
147			const service = new GameItemSelectionService([sourceOf("script", FIVE)]);
148	
149			// Draws: 0.0 of 5 -> "1"; 0.75 of the remaining 4 -> "5";
150			// 0.5 of the remaining 3 -> "3". Then one roll per item:
151			// 0.1 < 0.5 -> dictation, 0.9 -> reading, 0.49 < 0.5 -> dictation.
152			const round = service.selectRound(
153				{ ...SCRIPT_ONLY, itemCount: 3 },
154				scripted([0.0, 0.75, 0.5, 0.1, 0.9, 0.49]),
155			);
156	
157			expect(
158				round.map((item) => [item.symbolCharacter, item.challengeDirection]),
159			).toEqual([
160				["1", "dictation"],
161				["5", "reading"],
162				["3", "dictation"],
163			]);
164		});
165	
166		it("treats a symbol with cards under several properties as one item", () => {
167			const character = (consonants[0] as (typeof consonants)[number]).character;
168			const cards = (
169				["recognition", "class", "initialSound"] as PropertyType[]
170			).map(
171				(property, index) =>
172					new ScriptPropertyCard(
173						`card-${index}`,
174						`question ${index}`,
175						`answer ${index}`,
176						[],
177						SrsSchedule.initial(),
178						character,
179						property,
180						1,
181					),
182			);
183			const repository: CardRepository = {
184				findById: () => null,
185				findDue: () => [],
186				findAll: (pool: CardPool) => (pool === "script" ? [...cards] : []),
187				save: () => {},
188				saveAll: () => {},
189				remove: () => {},
190			};
191			const service = new GameItemSelectionService([
192				new SymbolGameItemSource(repository),
193			]);
194	
195			const round = service.selectRound(
196				{ ...SCRIPT_ONLY, itemCount: 3 },
197				scripted([0.0, 0.5]),
198			);
199	
200			expect(
201				round.filter((item) => item.symbolCharacter === character),
202			).toHaveLength(1);
203		});
204	
205		it("never assigns dictation to a symbol with no audio", () => {
206			const service = new GameItemSelectionService([
207				sourceOf("script", [
208					symbolContent("silent"),
209					symbolContent("loud", "/audio/loud.mp3"),
210				]),
211			]);
212			const rng = scripted([0.0, 0.13, 0.27, 0.41, 0.55, 0.68, 0.82, 0.96]);
213			const directions = new Set<string>();
214	
215			for (let round = 0; round < 200; round++) {
216				for (const item of service.selectRound(
217					{ ...SCRIPT_ONLY, itemCount: 2 },
218					rng,
219				)) {
220					if (item.symbolCharacter === "silent") {
221						expect(item.challengeDirection).toBe("reading");
222					} else {
223						directions.add(item.challengeDirection);
224					}
225				}
226			}
227	
228			// The run really did vary — otherwise "always reading" proves nothing.
229			expect([...directions].sort()).toEqual(["dictation", "reading"]);
230		});
231	
232		it("clamps and floors a degenerate requested count", () => {
233			const service = new GameItemSelectionService([sourceOf("script", FIVE)]);
234			const cases: ReadonlyArray<readonly [number, number]> = [
235				[0, 0],
236				[-1, 0],
237				[2.5, 2],
238				[Number.NaN, 0],
239				[1e9, 5],
240			];
241	
242			for (const [requested, expected] of cases) {
243				const startedAt = Date.now();
244				const round = service.selectRound(
245					{ ...SCRIPT_ONLY, itemCount: requested },
246					scripted([0.2, 0.4, 0.6, 0.8]),
247				);
248				expect(round).toHaveLength(expected);
249				expect(Date.now() - startedAt).toBeLessThan(50);
250			}
251		});
252	
253		it("draws only from the pools the round asks for", () => {
254			const service = new GameItemSelectionService([
255				sourceOf("script", FIVE),
256				sourceOf("vocab", [symbolContent("unused", "/audio/unused.mp3")]),
