 * have at least one card.
 */
export function worstStats(
	stats: readonly ScheduleStats[],
): ScheduleStats | undefined {
	return stats.reduce<ScheduleStats | undefined>(
		(worst, current) =>
			!worst || current.easeFactor < worst.easeFactor ? current : worst,
		undefined,
	);
}

